package com.zxl.zxlaiagent.security;
import org.junit.jupiter.api.*;
import java.time.*;
import static org.junit.jupiter.api.Assertions.*;
class AuthenticationPgTest {
 SecurityDatabase db; AuthenticationService auth; String subject,tenant;
 @BeforeEach void setup(){db=SecurityDatabase.fromEnvironment();auth=new AuthenticationService(db);subject="test-"+java.util.UUID.randomUUID();tenant=subject+"-tenant";auth.provision(subject,subject,"synthetic-password",tenant,"employee");}
 @AfterEach void cleanup(){db.tx(c->{try(var s=SecurityDatabase.statement(c,"DELETE FROM lesson17.authorization_audit WHERE subject_id=?",subject)){s.executeUpdate();}try(var s=SecurityDatabase.statement(c,"DELETE FROM lesson17.subject WHERE subject_id=?",subject)){s.executeUpdate();}try(var s=SecurityDatabase.statement(c,"DELETE FROM lesson17.tenant WHERE tenant_id=?",tenant)){s.executeUpdate();}return null;});}
  @Test void oversizedAndUnknownCredentialsAreSafelyRejected(){assertEquals(401,assertThrows(SecurityFailure.class,()->auth.login(subject,"密".repeat(25),tenant)).status());assertEquals(401,assertThrows(SecurityFailure.class,()->auth.login("x".repeat(151),"password",tenant)).status());assertEquals(401,assertThrows(SecurityFailure.class,()->auth.login("unknown-user","password",tenant)).status());assertThrows(SecurityFailure.class,()->auth.provision("x".repeat(151),"oversized","password",tenant,"employee"));}
 @Test void passwordAndMembershipAreVerified(){assertThrows(SecurityFailure.class,()->auth.login(subject,"wrong",tenant));assertThrows(SecurityFailure.class,()->auth.login(subject,"synthetic-password","other"));var login=auth.login(subject,"synthetic-password",tenant);assertEquals(subject,auth.authenticate(login.credential()).subjectId());assertThrows(SecurityFailure.class,()->auth.authenticate("forged"));}
 @Test void opaqueCredentialAndCsrfOnlyPersistAsHashes(){var login=auth.login(subject,"synthetic-password",tenant);assertNotEquals(login.credential(),db.tx(c->{try(var s=SecurityDatabase.statement(c,"SELECT credential_hash FROM lesson17.auth_session WHERE session_id=?",login.actor().sessionId());var r=s.executeQuery()){r.next();return r.getString(1);}}));auth.validateCsrf(login.actor().ref(),login.csrfToken());assertThrows(SecurityFailure.class,()->auth.validateCsrf(login.actor().ref(),"forged"));assertEquals(subject,new AuthenticationService(SecurityDatabase.fromEnvironment()).authenticate(login.credential()).subjectId());}
  @Test void separateJvmRetainsSessionAfterRestart(@org.junit.jupiter.api.io.TempDir java.nio.file.Path folder)throws Exception{var login=auth.login(subject,"synthetic-password",tenant);var output=folder.resolve("restart.log");var process=new ProcessBuilder(java.nio.file.Path.of(System.getProperty("java.home"),"bin","java").toString(),"-cp",System.getProperty("surefire.test.class.path",System.getProperty("java.class.path")),"com.zxl.zxlaiagent.security.SecurityRestartProbe").redirectErrorStream(true).redirectOutput(output.toFile()).start();try{try(var writer=new java.io.OutputStreamWriter(process.getOutputStream(),java.nio.charset.StandardCharsets.UTF_8)){writer.write(login.credential()+"\n");}assertTrue(process.waitFor(20,java.util.concurrent.TimeUnit.SECONDS));assertEquals(0,process.exitValue());assertTrue(java.nio.file.Files.readString(output).contains("ACTOR="+subject));}finally{if(process.isAlive())process.destroyForcibly();}}
 @Test void csrfRotationInvalidatesOldToken(){var login=auth.login(subject,"synthetic-password",tenant);String fresh=auth.rotateCsrf(login.actor().ref());auth.validateCsrf(login.actor().ref(),fresh);assertThrows(SecurityFailure.class,()->auth.validateCsrf(login.actor().ref(),login.csrfToken()));}
 @Test void expiryAndRevocationInvalidateReferences(){var login=auth.login(subject,"synthetic-password",tenant);auth.revoke(login.actor().ref());assertThrows(SecurityFailure.class,()->auth.authenticate(login.credential()));assertThrows(SecurityFailure.class,()->auth.resolve(login.actor().ref()));var second=auth.login(subject,"synthetic-password",tenant);db.tx(c->{try(var s=SecurityDatabase.statement(c,"UPDATE lesson17.auth_session SET expires_at=now()-interval '1 second' WHERE session_id=?",second.actor().sessionId())){s.executeUpdate();}return null;});assertThrows(SecurityFailure.class,()->auth.authenticate(second.credential()));}
}
